export class ManufacturerListComponent implements OnInit {
  manufacturers: ManufacturerDto[] = [];
  showEditor = false;
  editingManufacturer: ManufacturerDto | null = null;
  manufacturerName = '';

  constructor(private manufacturerService: ManufacturerService, private messageService: MessageService) {}

  ngOnInit(): void { this.load(); }
  load(): void { this.manufacturerService.getManufacturers().subscribe({ next: (m) => this.manufacturers = m, error: () => this.messageService.showError('Unable to load manufacturers.'); }); }

  onCreate(): void { this.editingManufacturer = null; this.manufacturerName = ''; this.showEditor = true; }
  onEdit(m: ManufacturerDto): void { this.editingManufacturer = m; this.manufacturerName = m.name ?? ''; this.showEditor = true; }
  onClose(): void { this.showEditor = false; this.editingManufacturer = null; this.manufacturerName=''; }
  onNameInput(event: Event): void { this.manufacturerName = (event.target as HTMLInputElement).value; }
  onSave(): void { const name = this.manufacturerName.trim(); if (!name) return; const payload: ManufacturerDto = { id: this.editingManufacturer?.id, name }; this.manufacturerService.saveManufacturer(payload).subscribe({ next: (saved) => this.onSaved(saved), error: () => this.messageService.showError('Unable to save manufacturer.'); }); }
  private onSaved(saved: ManufacturerDto): void { this.messageService.showSuccess('Manufacturer saved'); if (this.editingManufacturer) { const index = this.manufacturers.indexOf(this.editingManufacturer); if (index >= 0) this.manufacturers.splice(index, 1, saved); else this.manufacturers.push(saved); } else { this.manufacturers.push(saved); } this.editingManufacturer = saved; this.showEditor = false; this.manufacturerName = ''; }
  onDelete(m: ManufacturerDto): void { if (m.id == null) return; const name = m.name ?? ''; if (!window.confirm(`Are you sure you want to delete ${name}?`)) return; this.manufacturerService.deleteManufacturer(m.id).subscribe({ next: () => this.remove(m), error: () => this.messageService.showError('Unable to delete manufacturer.'); }); }
  private remove(m: ManufacturerDto): void { const index = this.manufacturers.indexOf(m); if (index >= 0) this.manufacturers.splice(index, 1); }
  trackById(index: number, item: ManufacturerDto): number { return item.id ?? index; }
}
